mapper.select:
/* 관리자 키워드 목록 : 사용 안 함 포함 */

 WHERE K.DICT_USG_CD = #{dictUsgCd}

   AND K.KWRD_CLSF_NM = #{kwrdClsfNm}

   AND K.DEL_YN = 'N'
 ORDER BY K.SORT_SEQ, K.KWRD_DICT_SN

/* 키워드 한 행 */

 WHERE K.KWRD_DICT_SN = #{kwrdDictSn}
   AND K.DEL_YN = 'N'

/* AI 서버용 : 사용 중 행만 */

 WHERE K.DICT_USG_CD = #{dictUsgCd}
   AND K.USE_YN = 'Y'
   AND K.DEL_YN = 'N'
 ORDER BY K.SORT_SEQ, K.KWRD_DICT_SN

/* 같은 탭의 가장 큰 정렬순서 */
SELECT MAX(SORT_SEQ)
  FROM KWRD_DICT
 WHERE DICT_USG_CD = #{dictUsgCd}
   AND KWRD_CLSF_NM = #{kwrdClsfNm}
   AND DEL_YN = 'N'

/* 연결 코드가 그 그룹의 코드인지 */
SELECT COUNT(*)
  FROM COM_CD C
  JOIN COM_CD P
    ON P.COM_CD_SN = C.COM_CD_PRNT_SN
 WHERE C.COM_CD = #{comCd}
   AND P.COM_CD = #{codeGroup}

mapper.update:
/* 키워드 수정 : 용도·분류·정렬순서는 그대로 */
UPDATE KWRD_DICT
   SET ARTCL_NM      = #{keyword.artclNm}
     , KWRD_CN       = #{keyword.kwrdCn}
     , INTRP_RSLT_CN = #{keyword.intrpRsltCn}
     , MPNG_CD       = #{keyword.mpngCd}
     , RMRK_CN       = #{keyword.rmrkCn}
     , USE_YN        = #{keyword.useYn}
     , MDFR_ID       = #{actorId}
 WHERE KWRD_DICT_SN = #{keyword.kwrdDictSn}
   AND DEL_YN = 'N'

/* 키워드 삭제 */
UPDATE KWRD_DICT
   SET DEL_YN  = 'Y'
     , MDFR_ID = #{actorId}
 WHERE KWRD_DICT_SN = #{kwrdDictSn}
   AND DEL_YN = 'N'
